-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODExc24f95f6f3bc$doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf$CODExc24f95f6f3bc$,$CODEx7576eb54f540$The Copyright Act, 2059 (2002)$CODEx7576eb54f540$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2059,2002,20,$CODEx42977166ecdf$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "1\nThe Copyright Act, 2059 (2002) \nDate of Authentication and Publication  \n30 shrawan 2059 (15 August 2002)", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Amendment  by Some Nepal Acts relating to Export and Import and Intellectual Property Act, 2063      2 063.8.8", "content": "Act number 8 of the year 2059 (2002)  \nAn Act Made to Provide for Copyright  \nPreamble : Whereas, it is expedient to update the legal provis ions relating to copyright; \nNow, therefore, be it enacted by Parliament in the first year of reign of His Majesty the \nKing Gyanendra Bir Bikram Shah Dev.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter - 1", "title": "Chapter - 1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement : (1) This Act may be called as the", "content": "\"Copyright Act, 2059 (2002). \n  (2) This act shall come into forceimmediately. \n2. \nDefinitions:  Unless the subject or the context otherwise require, in this Act,- \n(a) \"Work\" means any work presented originally and intellectually in the \nfield of literature, art and science and in any oth er field, and this term \nalso includes the following work: \n(1) Book, pamphlet, article, thesis, \n(2) Drama, dramatic-music, dumb show and a work prepare d to \nperform in such manner, \n(3) Musical notation with or without words, \n(4) Audio visual works, \n(5) Architectural design, \n(6) Fine Arts, painting, work of sculpture, work of woo dcarving, \nlithography, and other work relating to architecture, \n(7) Photographic work, \n 2\n(8) Work of applied art, \n(9) Illustration, map, plan, three-dimensional work rel ating to \ngeography, and scientific article and work, \n(10) Computer program. \n(b) \"Author\" means a person who creates a work as referred to in clause (a) \nabove. \n(c) \"Audio-visual work\" means a cinematographic work that can be viewed \nin screen, with or without sound. \n(d) \"Photographic work\" means a work produced by using light or any other \nradiation recorded in the surface in such a manner that the image \n(picture) of any thing can be set in the surface or  that the image (picture) \ncan be created from such surface with the help of c hemical, electrical or \nany other technology. \nProvided, however, that a still photography taken f rom any audio-visual \nwork shall not be considered as a photographic work  but as a part of the \nconcerned audio-visual work. \n(e) \"Sound recording\" means the act of recording of sou nd of any \nperformance recorded in any manner and with any met hod whatsoever \nfor the purpose of hearing, except the act of recor ding sound and image \nat the same time. \n(f) \"Performance\" means,- \n(1) In the case of work other than the audio-visual wor k, performance \nmade through recitation, playing music, dancing, ac ting or any \nother manner, directly or with the help of any othe r device or \nmethod, \n(2) In the case of the audio-visual work, sequential vi deo clipping of \nthe scene contained in such a work, along with soun d for hearing \npurpose, \n 3\n(3) In the case of the sound recording, act of performa nce made \noutside the family circle, neighbors, friends or re latives or made \nin such manner that it can be heard publicly despit e the presence \nof such persons. \n(g) \"Economic right\" means the rights conferred on the copyright owner \npursuant to Section 7. \n(h) \"Copyright owner\" means the author of a work in cas es where the \neconomic right of that work is vested in that autho r, a person or \norganization in cases where the economic right of t he work is primarily \nvested in the person or organization other than the  author, and a person \nor organization, in cases where the economic right of the work is \ntransferred to that person or organization. \n(i) \"Broadcasting\" means communication or exhibition of a work for public \ninformation or broadcasting of audio or audio-visua l work through \nwireless equipment or satellite. \n(j) \"Communication to the public\" means the act of broad casting and audio \nor visual broadcasting or both either by wire or wi reless equipment in \nsuch a manner that it can be heard or viewed stayin g near or far from the \nplace of broadcasting. \n(k) \"Moral right\" means the right to be conferred to th e author or his \nsuccessor or any person authorized by the author pursuant to Section 8. \n(l) \"Performer\" means any actor, singer, musician, danc er and other person \nwho performs a literary or artistic work or folklor e expression to the \ngeneral public through acting, singing, music and dancing. \n(m) \"Publication\" means: \n(1) In the case of a work of drama, motion picture, or work \nperformed in any other manner, the shows, sale or r ental of such a \nwork publicly with or without translating or altering it, \n(2) In the case of any other work, the work which has b een publicly \nsold, distributed or utilized or so brought out as to be sold and \n 4\ndistributed or utilized publicly, with or without t ranslating or \naltering it; and, in the case of a work that can be exhibited through \nacting, this term includes its exhibition in a publi c manner with or \nwithout translating or altering it. \n(n) \"Registrar\" means the person specified pursuant to Sub-section (1) of \nSection 30. \n(o) \"Royalty collecting body\" means the body formed pur suant to Section \n39. \n(p) \"Prescribed\" or \"as prescribed\" means prescribed or  as prescribed in the \nRules framed under this Act.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": "Chapter-2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Protection of copyright : (1) Copyright protection shall be extended to any", "content": "work. \n  (2) Any translation, arrangement, sequential arra ngement of work or \ncollection of works presented as original from view point of presentation, \ncollection or expression, data or database readable  with or without support of \nmachine, any proverb, folktale, folk song falling u nder folk expression or any \nother derivate works based on folk expression shall  be protected as original \nwork, without prejudice to the copyright of the original work.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Non-availability of copyright protection : Notwithstanding anything", "content": "contained in Section 3, copyright protection under this Act shall not be \nextended to any thought, religion, news, method of operation, concept, \nprinciple, court judgment, administrative decision,  folksong, folktale, proverb \nand general data despite the fact that such matters  are expressed or explained or \ninterpreted or included in any work.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Registration not compulsory : (1) Registration of a work, sound recording,", "content": "performance or broadcasting shall not be required t o acquire the right under this \nAct. \n 5\n  (2) Notwithstanding anything contained in sub-sec tion (1), in cases \nwhere any person intends to get any work, sound rec ording, performance or \nbroadcasting registered voluntarily, that person ma y make an application to the \nRegistrar and get the same registered; and the proc edures on registration shall \nbe as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Owner of economic right of work : (1) The author of a work shall be the", "content": "first owner of the economic right of that work. \n  (2) Notwithstanding anything contained in Sub-sec tion (1), the economic \nright of a work shall vest in the following person or organization in the \nfollowing circumstances:- \n(a)  Co-author in the case of a joint work; \nProvided, however, that where such a joint work is divided in \ndifferent parts and each part can be identified as of different \nauthors and  the work can be used separately, the e conomic right \nshall vest in  the concerned author in respect of e ach part created \nby that author. \n(b)  In cases where a joint work is prepared at the ini tiation or \n direction of any person or organization, that pers on or \n organization at whose direction or initiation such  a work has been \n so prepared, \n(c)  In case where a work is prepared on payment of rem uneration by \n any person or organization, that person or organiz ation who has \n paid such remuneration, \n(d)  In the case of an anonymous work, the publisher of  that work, \n until the authorship of such a work is proved. \n  Provided, however, that in cases where the real a uthor of such a \n  work presents his/her identity subsequently, the economic right of \n  that work shall vest in that author from the date of presentation of \n  his/her identity. \n 6\n(e)  In the case of an audio-visual work, the producer of such a work \n except as otherwise provided for in the contract. \n  Provided, however, that in case where the work of  the co-author \n  of an audio-visual work or a pre-existing work is  incorporated or \n  adapted in making the audio-visual work, their ec onomic right \n  shall be according to their respective contributi on.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Economic Right : Subject to provisions of Chapter-4, only the autho r or the", "content": "owner of copyright shall have the exclusive right t o carry out the following acts \nin respect of the work: \n(a) To reproduce the work, \n(b) To translate the work, \n(c) To revise or amend the work, \n(d) To make arrangement and other transformation in the work, \n(e) To sell, distribute or rent the original and copy o f the work for the \n  general public, \n(f) To transfer or rent the right of audiovisual work, work embodied \n  in sound recording, computer program or musical wo rk in graphic \n  form conferred to that author or owner, \n(g) To import copies of the work, \n(h) To have public exhibition of the original or copy of the work, \n(i) To perform the work in public, \n(j) To broadcast the work, \n(k) To communicate the work to the general public.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Moral right : (1) The author of a work shall have the following moral rights,", "content": "irrespective of whether that author has the economic right to that work: \n(a) To get his/her name mentioned in copies of the work or in his/her  \nwork  where it is used publicly, \n 7\n(b)  In cases where, instead of his/her real name, a ps eudonym is \n mentioned in his work, then to get that pseudonym mentioned \n while using such a work publicly, \n(c)  To prevent such acts as undermining the reputation  or goodwill \n earned by him/her, by mutilating his/her work or p resenting it in a \n distorting manner, \n(d)  To make necessary amendment or revision in the work . \n(2) The right referred to in sub-section (1) shall not be transferable \nduring the life of the author. \nProvided, however, that where the author has nomina ted any one whom \nsuch right is to be transferred after the death of the author, such right shall \ndevolve on the person or organization so nominated,  and on the nearest heir, \nfailing such nomination.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Rights of performer : (1) The performer shall have the right to perform the", "content": "following acts:- \n(a) To take one's performance to the general public thr ough \n broadcasting or communication, \n(b) To determine modality or medium of making one's per formance \n and reproduce it, \n(c) To take one's performance to the general public for  the first time \n by making performance or selling or transferring c opies thereof or \n changing ownership, \n(d) To rent copies of one's performance, \n(e) To take the performance produced through the determ ined \n modality or medium to the general public in an easi ly available \n manner, through wire or wireless equipment, \n(f) To amend or revise one's performance. \n 8\n(2) The performer shall not be allowed to re-exerci se the rights \nmentioned in Sub-section (1) once he/she has author ized his/her performance to \nbe incorporated in audio-visual medium. \n(3) Notwithstanding anything contained in Sub-section (2), the performer \nshall have the right to have his/her identity maint ained as the performer of \ndirect audio performance as well as of the performa nce incorporated in the \nsound recording and to make a claim for the same, a nd, where any person has \nso mutilated or distorted his/her performance or ot herwise deformed his \nperformance by mutilating the meaning as to prejudi ce his/her reputation or \ngoodwill, to prevent such acts. \n(4) Nothing mentioned in this Section shall be deem ed to have any effect \non the right of a performer to enter into, or to be  agreed on, an agreement with \nsuch terms as may yield much more benefits or facil ities to him/her from the  \nperformance. \n(5) The right conferred to the performer pursuant t o this Section shall be \nprotected for a period of fifty years from the year of incorporation of \nperformance in sound recording device, and for a pe riod of fifty years from the \nyear of such performance where such incorporation has not been made.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Right of sound recording producer : (1) The sound recording producer", "content": "shall have the following rights:- \n(a) To reproduce the sound recording, directly or indir ectly, in \nany manner or in any form, \n(b) To import copies of the sound recording, \n(c) To make the sound recording easily available by way  of sale \nor ownership transfer or otherwise of the original or copies of \nthe sound recording, \n(d) To rent or lease the sound recording publicly, \n(e) To make the sound recording capable of being heard with \nwire or wireless equipment from any specific place or from \nthe place of one's own choice or by the general public. \n 9\n(2) The term of the right referred to in sub-sectio n (1) shall be of fifty \nyears from the year of publication of such a sound recording.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Reasonable remuneration for the use of sound record ing : (1) In cases", "content": "where a sound recording published for commercial pu rpose or a reproduced \ncopy of such sound recording is directly used for b roadcasting or other \ncommunications and is so performed to the people pub licly, the producer shall \nget a reasonable remuneration from the user of the same. \n (2) The performer shall get the remuneration as pe r the agreement, in \nany, made between the performer and the producer on the remuneration referred \nto in Sub-section (1), and half the amount received  by the producer where no \nsuch agreement is made. \n (3) The term of the right to receive reasonable rem uneration under Sub-\nsection (1) shall be for fifty years from the year of publication of such a sound \nrecording or from the year of adjustment of such a sound recording. \n12. \nRight of broadcasting organization : (1) The broadcasting organization \nshall have the right to carry out the following act:- \n(a) To re-broadcast the subject it has broadcast, \n(b) To so communicate its broadcast as to make it easily  available to the \ngeneral public, \n(c) To make adjustment of its own broadcast, \n(d) To reproduce the adjustment of its broadcast. \n(2) The term of the right referred to in sub-sectio n (1) shall be for fifty \nyears from the year of commencement of such broadcast. \n*13.  Protection of work, performer, sound recording prod ucer or \nbroadcasting organization  : (1) A work of the following author shall enjoy \nprotection under this Act: \n                                                   \n*  Amendment by the  Act Made to Amend Some Nepal Acts relating to Export and Import and Intellectual Property  \n 10 \n(a) A work created by the author residing in Nepal or in a member country of \nthe World Trade Organization and published in the N epal or in that \ncountry, \n(b) An audio-visual work produced by a producer res iding in Nepal or in a \nmember country of the World Trade Organization, \n(c) An architectural design of a building made in t he Nepal or in a member \ncountry of the World Trade Organization or other ki nd of artistic work \nused in a building or any other structure, \n(d) A work published in Nepal by an author residing  in a country other than \nNepal or a member country of the World Trade Organi zation or an audio-\nvisual work produced in the Nepal by a producer of such other country. \n  (2) The following performer shall be entitled to the rights relating to \nperformer as referred to in this Act: \n(a) A performer of Nepal or a member country of the  World Trade \nOrganization, \n(b) A performer of the performance made in Nepal or  in a member \ncountry of the World Trade Organization or of the p erformance \ncontained in the sound recording protected under th is Act or of the \nperformance contained in a broadcast even though it  is not \ncontained in the sound recording. \n  (3) The following sound recording producer shall be entitled to the \nrights relating to sound recording producer as referred to in this Act: \n(a) A sound recording produced by a person in Nepal  or a member \ncountry of the World Trade Organization, \n(b) A sound recording published in Nepal or in a mem ber country of \nthe World Trade Organization. \n   (4) The following broadcasting organization shal l be entitled \nto the rights relating to broadcasting organization as referred to in this Act: \n 11 \n(a)  A broadcast by a broadcasting organization wit h its office in \nNepal or in a member country of the World Trade \n Organization, \n(b)  A Broadcast by a broadcasting station situated  in Nepal or in a \nmember country of the World Trade Organization. \nChapter: 3  \nTerm of protection of Copyright", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Term of protection of copyright : (1) The economic and moral rights", "content": "available to the author under this Act shall be pro tected throughout the life of \nthe author and in the case of his/her death until f ifty years computed from the \nyear of his death. \n (2) The economic and moral rights over the work pr epared jointly shall \nbe protected for fifty years computed from the year  of death of the last \nsurviving author. \n (3) The economic and moral right of the work prepa red pursuant to \nClauses (b) and (c) or Sub-section (2) of Section 6  shall be protected until fifty \nyears from the date of first publication of such wo rk or the date on which the \nwork is made public, whichever is earlier. \n (4) The economic and moral right of the work publi shed anonymously or \nwith pseudonym name shall be protected until fifty years from the date of first \npublication of such work or the date on which the w ork is made public, \nwhichever is earlier. \n Provided, however, that in cases where the name of  author is published \nwithin that period of time, the protection referred  to in Sub-section (1) or (5) \nshall be available depending on the case. \n (5) The economic and moral right of a work relatin g to applied art and \nphotographic work shall be protected until twenty-f ive years from the year of \npreparation of such work. \n15. \nTerm of protection of work published after the deat h of author : \nNotwithstanding anything contained in Section 14, t he work published after the \n 12 \ndeath of the author where there is only one author of such work and after the \ndeath of one of the authors where there are two or more authors shall be \nprotected until fifty years from the year of publication of that work.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": "Chapter-4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "16", "title": "Reproduction allowed for personal purpose : (1) Notwithstanding", "content": "anything contained in Clause (a) of Section 7, no a uthorization shall be required \nfrom the author or the copyright owner to reproduce  some portions of any \npublished work for personal use. \n (2) Notwithstanding anything contained in Sub-sect ion (1), no \nreproduction of an architectural design erected as a building and other \nconstruction related design or a significant portio n of any book or of a musical \nwork as notation of all or significant portion of a  database through digital \ntransmission shall be allowed in a manner to be pre judicial to the economic \nright of the author or the copyright owner. \n17. \nCitation allowed : Notwithstanding anything contained in Clause (a) o f \nSection 7, some portions of a published work can be  cited for fair use without \nauthorization of the author or the copyright owner in a manner not to be \nprejudicial to the economic right of such author or  owner. In making such \ncitation, its source and the author' name, in cases  where it appears, shall also be \nmentioned.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Reproduction allowed for teaching and learning : (1) Notwithstanding", "content": "anything contained in Clause (a) of Section 7, the following acts may be done \nfor teaching and learning activities without author ization of the author or the \ncopyright owner in a manner not to be prejudicial to  the economic right of such \nauthor or owner:- \n(a) To reproduce a small portion of any published work by way of \ncitation, writing or audio-visual aid, \n 13 \n(b) To reproduce, broadcast and exhibit some portions o f the work for \npurposes of educational activities to be performed in the classroom. \n(2) All copies reproduced pursuant to Sub-section ( 1) have to indicate \nthe source and the author's name.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Reproduction by library and archives : Notwithstanding anything", "content": "contained in Clause (a) of Section 7, in cases wher e a public library or archives, \nwhich makes available the work stored in it at the request of a person doing \nresearch or study without deriving economic profits  directly or indirectly, \nlooses any work with it or such work is destroyed o r is old or is incapable of \nbeing obtained, it may reproduce one copy of such a  work without authorization \nof the author or the copyright owner of such work.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Reproduction, broadcast and other communication all owed for", "content": "purposes of information to the general public : (1) Notwithstanding \nanything contained in clauses (a), (i) and (j) of S ection 7, the following acts can \nbe done, by mentioning the sources and name of the author of any work, \nwithout authorization of the author or the copyright owner of such work. \n(a) To print in any newspaper or journal or to make bro adcast or other \ncommunication to public of any article, article unde r political or \nreligious topics or similar other broadcasts publish ed in any \nnewspaper or journal. \n Provided, however, that such act shall not be prej udicial to the \neconomic right of the author or the copyright owner. \n(b) To reproduce, broadcast or otherwise communicate or justify any \nevent with a view to informing the general public ab out any \ncurrent event. \n(c) To reproduce, broadcast or to make communication to public some \nportions of any regular newspaper or journal regula rly publishing \ninformation for communication to the general public or pleadings \nmade on court proceedings with a view to disseminati ng current \ninformation. \n 14 \n(2) Notwithstanding anything contained in Sub-secti on (1), in cases \nwhere the author himself/herself has indicated that his/her work is prohibited \nfrom being reproduced, broadcast and other kinds of  communications, no \nreproduction, broadcasting and other communication shall be allowed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Reproduction of computer program : Notwithstanding anything contained", "content": "in Clauses (a) and (c) of Section 7, in cases where  the objectives for which a \ncomputer program was acquired could not be achieved  or with a view to \nmaintaining records or where the computer program a cquired legally is lost or \ndestroyed or is incapable of being used, one copy o f the computer program can \nbe reproduced without authorization of its author or copyright owner.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Importation allowed for personal purposes : Notwithstanding anything", "content": "contained in Clauses (g) of Section 7, one copy of any work can be imported for \npersonal purpose, without authorization of its author or copyright owner.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Public exhibition allowed : Notwithstanding anything contained in clauses", "content": "(h) of Section 7, in cases where any person intends  to have public display of \nany work or copy of the work, he may do so without authorization of its author \nor copyright owner. \n  Provided, however, that such public display has t o be made without the \nhelp of film, slide, television image or otherwise using the screen or device of \nother kind.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": "Chapter-5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "24", "title": "Transfer of Copyright : (1) The copyright owner may transfer all or any of", "content": "the economic rights conferred on him/her to any one  by making a written \nagreement or authorize any one to use the same with  or without specifying any \nterms. \n (2) The person entitled to moral rights may, for t he protection of moral \nrights, transfer his moral rights to any one, with effect after his/her death, by \nmaking a written agreement, with the terms and cond itions that his/her name \nshall not be removed from the work. \n 15 \n (3) The person to whom the rights are transferred by the copyright owner \npursuant to this Section shall not carry out any ot her activities except the rights \nso transferred.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": "Chapter-6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "25", "title": "Infringement of protected right : (1) Any one who carries out the following", "content": "act shall be considered to have infringed the right protected under this Act:- \n(a) To reproduce copies of a work or sound recording an d sell and \ndistribute them or publicly communicate or rent the m with \ncommercial or any other motive with or without deriving economic \nbenefits without authorization of the author or the  copyright owner \nor by infringing the terms contained in the agreeme nt or license \nnotwithstanding that such authorization has been obtained, \n(b) To do advertisement or publicize by copying a work belonging to \nanother person with a motive of taking advantage of  the reputation \ngained by that work, \n(c) To make work of another subject or nature by changi ng the form \nand language of a work belonging to another person with a motive \nof deriving economic benefit, \n(d) To make an attempt to take benefit by adapting any work directly \nor indirectly with intention of making the viewer, listener or reader \nbelieve it to be another work through advertisement  or by any \nother means, \n(e) To import, produce or rent any equipment or device prepared with \nintention of circumventing any device designed to di scourage the \nunauthorized reproduction,  \n(f) To produce or import, with intent to sell, any equi pment \nfacilitating unauthorized reception of a program bro adcast by \nencrypting it in a code language, \n 16 \n(g) To import, sell, distribute and use a mechanical de vice prepared \nwith a sole object of infringing the copyright, exc ept those \nmentioned in Clauses (e) and (f). \n(2) No one shall, with knowledge of publication of any work or sound \nrecording or where there is adequate ground to beli eve it, sell and distribute and \nrent copies of work or sound recording so published , in contravention of sub-\nsection (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Restriction on the importation of unauthorized copi es : Importation of", "content": "copies of work or sound recording, either made in a  foreign country or sourced \notherwise, into Nepal for business purpose shall no t be permitted if preparation \nof such copies would be considered illegal if they were prepared in Nepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Punishment on infringement of protected right : (1) In cases where any", "content": "person infringes Section 25, such a person shall be  punished with a fine of a \nsum from ten thousand to one hundred thousand rupees or with imprisonment \nfor a term not exceeding six months or both and wit h a fine of a sum from \ntwenty thousand to two hundred thousand rupees or w ith imprisonment for a \nterm not exceeding one year or with both for each i nstance from the second \ntime. The materials so published or reproduced or d istributed or devices used to \nreproduce such materials shall be seized. \n  (2) Compensation for the loss caused to the copyr ight owner by the \ninfringer of the protected right shall also be real ized and provided to the \ncopyright owner.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Punishment for importation of unauthorized copy : In cases where any", "content": "person imports unauthorized copies of any work in violation of Section 26, such \na person shall be punished with a fine of a sum fro m ten thousand to one \nhundred thousand rupees according to the gravity of  the offense, and such \ncopies shall be seized; and compensation for the lo ss caused to the copyright \nowner from such importation shall also be realized from the importer and \nprovided to the copyright owner. \n 17", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Other punishment : In cases where any person infringes any other matt er", "content": "contained in this Act or the Rules framed under this  Act, such a person shall be \npunished with a fine of a sum from five thousand to fifty thousand rupees \naccording to the gravity of the offense.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-7", "title": "Chapter-7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "30", "title": "Registrar and his functions, duties and powers : (1) Government of Nepal", "content": "may, by a notification in the Nepal Gazette, design ate any officer of at least \nGazetted second class to act as the Registrar pursuant to this Act. \n  (2) In addition to those mentioned elsewhere in t his Act, the functions, \nduties and powers of the Registrar shall be as follows: \n(a) To monitor and control the royalty collecting body, \n(b) To hear complain as prescribed made by any party wh o is not \n satisfied with the royalty fixed by the royalty co llecting body, \n(c) To perform, or cause to be performed such other fun ctions as \n prescribed for the accomplishment of the objective  of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Appeal against order and decision of Registrar : An party who is not", "content": "satisfied with any order or decision made by the Re gistrar may make an appeal \nin the Appellate Court in the area where the Office  of the Registrar is situated, \nwithin thirty-five days.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Power to seize copies of work, sound recording or o ther materials : (1)", "content": "In cases where any person doubt that any one has pu blished or reproduced or is \nabout to publish or reproduce any work or sound rec ording contrary to Section \n25 and makes a complaint before the police who has a duty of investigating the \noffense under this Act, the police shall make neces sary arrangements for \npreventing the copies of such work or sound recordi ng from being sold and \ndistributed and may, in cases where required, searc h the copies of such work or \nsound recording and seize the same pursuant to the law in force. \n 18 \n (2) In conducting search and seizure pursuant to S ub-section (1), the \nmachine including materials used to publish and rep roduce the copies of such \nwork or sound recording may also be seized.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "To destroy copies of work, sound recording or other  materials : In", "content": "cases where the copies of the work or sound recordi ng seized pursuant to \nSection 32 are held by the court liable to be seize d, they shall be destroyed in \npresence of the representatives of the District Adm inistration Office and the \nLocal body.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Power of Customs Officer to stop importation of una uthorized copies :", "content": "(1) In cases where any person suspects that any oth er person is importing \ncopyrighted materials into Nepal in an unauthorized  manner, such a person may \nmake an application, accompanied by the evidence, t o the Custom Officer to \nprevent the importation of such material. \n (2) In cases where, in conducting necessary invest igation upon receipt of \nan application pursuant to Sub-section (1), the dem and of the applicant appears \nreasonable, the Customs Officer may prevent the mat erials to be imported for a \nmaximum of twenty working days at the rate of ten working days at a time. \n (3) Notwithstanding anything contained in Sub-sect ions (1) and (2), in \ncases where the Customs Officer learns or suspects that any one is importing \ncopyright reserved materials into in an unauthorize d manner, he/she may \nprevent such materials for a maximum of twenty work ing days at the rate of ten \nworking days at a time. \n(4) Other procedures on the prevention of importati on of unauthorized \ncopies shall be as prescribed. \n35. \nTo try and settle cases : (1) The concerned District Court shall have the \npowers to try and settle cases punishable under this Act. \n (2) In trying and settling cases under this Act, t he procedures referred to \nin the Summary Procedures Act, 2028 (1971) shall be followed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Power to order for withholding : In cases where, in the course of trying and", "content": "settling a compliant pursuant to this Act, the Dist rict Court, at the request of the \n 19 \nconcerned party, thinks it reasonable to stop any a ctivity contrary to this Act, it \nmay order the concerned person or body to stop such activity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "To be state cases : (1) The cases punishable under Sections 27 and 28  shall be", "content": "state cases and those cases shall be considered to be included in Schedule-1 of \nthe State Cases Act, 2049 (1992). \n (2) A police officer of at least the rank of polic e inspector shall \ninvestigate and inquire into the cases under this Act. \n38. \nLimitation:  In cases where any right under this Act is infring ed, a case has to \nbe filed within three months of the knowledge of such infringement.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Provisions relating to royalty collecting body : (1) Generally, one royalty", "content": "collecting body shall be formed as prescribed in on e discipline for the purposes \nof fixing, collecting and distributing royalty of the works relating to copyright. \n (2) The royalty collecting body formed pursuant to  Sub-section (1) has to \nbe registered with the Registrar in the manner as prescribed. \n (3) The royalty collecting body shall be an autono mous body corporate \nwith perpetual succession. \n (4) The royalty collecting body shall have a seal of its own for all of its \nactivities. \n (5) The royalty collecting body may, like an indiv idual, acquire, use, sell \nand dispose of or otherwise manage movable and immovable property and may, \nlike an individual, sue and be sued by its name. \n (6) Government of Nepal may specify the terms to b e followed by the \nroyalty collecting body; and it shall be the duty o f the royalty collecting body to \nabide by such terms. \n40. \nCopyright Government of Nepal : (1) Government of Nepal shall have the \ncopyright over the work prepared by Government of Nepal. \n (2) Government of Nepal may rent or sell the right  accrued to it pursuant \nto sub-section (1) to any person or organization or  give authorization to use the \nsame in any other manner. \n 20", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Calculation of year:  In calculating a year pursuant to this Act, it sha ll be", "content": "calculated from the New year as per Bikram Sambat  that starts from the end of \nthe year on which the work was published or communi cated publicly or sound \nrecording was produced.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Powers to frame rules : Government of Nepal may frame necessary Rules in", "content": "order to carry out the objectives of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Repeal and saving : (1) The Copyright Act, 2022 (1965) is hereby repea led.", "content": "(2) The remaining term of protection of the copyrig ht of a work \npublished publicly prior to the commencement of this  Act shall be deemed to \nhave been protected pursuant to this Act. \n (3) The acts and actions done and taken under the Copyright Act, 2022 \n(1965) shall be deemed to have been done and taken under this Act.", "children": []}]}]$CODEx42977166ecdf$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
